WITH base AS (SELECT id, channel, promo_code, ends_on, discount_pct, CONCAT_WS('/', channel, promo_code) AS channel_promo_code_key, ROUND(DATEDIFF(starts_on, ends_on) / 30, 1) AS months_ends_on_to_starts_on, COALESCE(channel, 'DIRECT') AS channel_filled FROM promotions WHERE channel IS NOT NULL) SELECT id, promo_code, measure, metric_value FROM (SELECT id, promo_code, discount_pct, months_ends_on_to_starts_on FROM base) src UNPIVOT (metric_value FOR measure IN (discount_pct AS DISCOUNT_PCT, months_ends_on_to_starts_on)) long_rows
